-- | Checks on rendered pages, run before anything is published.
--
-- Pages are generated by this program, so a few string scans are enough:
-- Brigid renders every attribute as @ name="value"@. The checks are:
--
-- * the document is complete (doctype, @<html lang>@, @<title>@, @<main>@)
--   and has exactly one @<h1>@;
-- * no element id is repeated;
-- * every internal @href@/@src@ is root-absolute and names a file in the
--   manifest, and every @#fragment@ names an id on its target page;
-- * no tag carries active content: no @<script>@, @<iframe>@, @<object>@,
--   @<embed>@ or @<style>@ element, and no @on…=@ event-handler attribute.
--   The site uses none of these (the one exception is an external module
--   script from @/assets/scripts/@, in exactly one form; see
--   'sitePageScript'), so any occurrence means content escaped its
--   attribute or text (see 'activeContent').
--
-- External @http(s):@ and @mailto:@ URLs are not fetched.
module Site.Validate
  ( PageProblem (..)
  , validatePages
  , attributeValues
  , activeContent
  ) where

import Data.Char (isAsciiLower, isDigit, isSpace)
import Data.List (group, sort)
import Data.Map.Strict qualified as Map
import Data.Text qualified as T

import Site.Manifest (Entry (..), Manifest, Source (..), lookupOutput)
import Site.Path (outputText)
import Site.Routes (Route, routePath, urlPathOutput)

data PageProblem
  = IncompleteDocument Route String
  | HeadingCount Route Int
  | DuplicateId Route T.Text
  | BrokenLink Route T.Text String
    -- ^ The page, the URL, and why it does not resolve.
  | ActiveContent Route T.Text
    -- ^ A tag that would run script (see 'activeContent').
  deriving (Eq)

instance Show PageProblem where
  show problem =
    case problem of
      IncompleteDocument route what -> page route <> " is not a complete document: " <> what
      HeadingCount route n -> page route <> " must have exactly one <h1>, found " <> show n
      DuplicateId route ident -> page route <> " repeats the element id " <> show (T.unpack ident)
      BrokenLink route url why -> page route <> " links to " <> show (T.unpack url) <> ": " <> why
      ActiveContent route tag ->
        page route <> " contains active content in the tag " <> show (T.unpack (T.take 120 tag))
          <> " (an attribute or text value broke out of its context)"
    where
      page route = "page " <> T.unpack (routePath route)

-- | Validate every rendered page against the manifest.
validatePages :: Manifest -> [(Route, T.Text)] -> [PageProblem]
validatePages manifest pages = concatMap check pages
  where
    idsByRoute = Map.fromList [ (route, attributeValues "id" html) | (route, html) <- pages ]

    check (route, html) =
      structure route html
        <> [ ActiveContent route tag | tag <- activeContent html ]
        <> [ DuplicateId route ident | ident : _ : _ <- group (sort (attributeValues "id" html)) ]
        <> concatMap (link route) (attributeValues "href" html <> attributeValues "src" html)

    link route url
      | any (`T.isPrefixOf` url) ["https://", "http://", "mailto:"] = []
      | "//" `T.isPrefixOf` url = [BrokenLink route url "protocol-relative URLs are not allowed"]
      | Just fragment <- T.stripPrefix "#" url = fragmentOn route route url fragment
      | "/" `T.isPrefixOf` url =
          let (path, rest) = T.breakOn "#" url
           in case urlPathOutput path of
                Left err -> [BrokenLink route url (show err)]
                Right output ->
                  case lookupOutput output manifest of
                    Nothing -> [BrokenLink route url (outputText output <> " is not generated")]
                    Just entry ->
                      case (T.stripPrefix "#" rest, entrySource entry) of
                        (Nothing, _) -> []
                        (Just fragment, PageSource target) -> fragmentOn route target url fragment
                        (Just _, AssetSource _) -> [BrokenLink route url "fragment on an asset"]
                        (Just _, MediaSource _) -> [BrokenLink route url "fragment on a media file"]
                        (Just _, GeneratedSource _) -> [BrokenLink route url "fragment on a generated file"]
      | otherwise = [BrokenLink route url "relative URLs are not allowed; use a root-absolute URL"]

    fragmentOn route target url fragment
      | T.null fragment = [BrokenLink route url "empty fragment"]
      | fragment `elem` Map.findWithDefault [] target idsByRoute = []
      | otherwise =
          [BrokenLink route url ("no element with id " <> show (T.unpack fragment) <> " on " <> T.unpack (routePath target))]

structure :: Route -> T.Text -> [PageProblem]
structure route html =
  [ IncompleteDocument route what | (what, ok) <- requirements, not ok ]
    <> [ HeadingCount route h1s | h1s /= 1 ]
  where
    h1s = length (T.breakOnAll "<h1" html)
    requirements =
      [ ("missing <!DOCTYPE html>", "<!DOCTYPE html>" `T.isPrefixOf` html)
      , ("missing <html lang>", "<html lang=\"" `T.isInfixOf` html)
      , ("missing <title>", "<title>" `T.isInfixOf` html)
      , ("missing <main>", "<main " `T.isInfixOf` html)
      , ("missing </html>", "</html>" `T.isSuffixOf` T.strip html)
      ]

-- | Tags that would run script. Brigid escapes @<@ in text, so every
-- literal @<@ in the output starts a real tag; each tag (up to its @>@) is
-- checked for a script-capable element name or an attribute named @on…@
-- (an event handler) appearing after whitespace.
activeContent :: T.Text -> [T.Text]
activeContent html =
  [ tag
  | chunk <- drop 1 (T.splitOn "<" html)
  , let tag = T.takeWhile (/= '>') chunk
        name = T.toLower (T.takeWhile (\c -> not (isSpace c) && c /= '/' ) tag)
  , (name `elem` ["script", "iframe", "object", "embed", "style", "frame", "frameset", "applet", "base"]
       && not (name == "script" && sitePageScript chunk))
      || any handler (attributeNames tag)
  ]
  where
    handler n = "on" `T.isPrefixOf` n && T.length n > 2 && T.all isAsciiLower (T.drop 2 n)
    -- every word immediately followed by '=' and preceded by whitespace
    attributeNames tag =
      [ T.toLower (T.takeWhileEnd (not . isSpace) before)
      | (before, _) <- T.breakOnAll "=" tag
      , not (T.null before)
      , T.any isSpace before
      ]

-- | The one form of script the site emits (Phase 05: the Work index's
-- search and filter enhancement): exactly
-- @<script src="/assets/scripts/NAME.js" type="module"></script>@, with
-- no other attribute and no inline code. NAME is lowercase letters, digits
-- and hyphens. The link checker separately requires the file to be a listed
-- asset, so only reviewed code in @assets/scripts/@ can ever run. Takes the
-- text after the tag's @<@, up to the next @<@.
sitePageScript :: T.Text -> Bool
sitePageScript chunk =
  T.null inline
    && case sort (T.words (T.drop (T.length "script") tag)) of
         [srcAttr, typeAttr] -> typeAttr == "type=\"module\"" && validSrc srcAttr
         _ -> False
  where
    tag = T.takeWhile (/= '>') chunk
    inline = T.drop 1 (T.dropWhile (/= '>') chunk)
    validSrc a =
      case T.stripPrefix "src=\"/assets/scripts/" a >>= T.stripSuffix ".js\"" of
        Just name -> not (T.null name) && T.all (\c -> isAsciiLower c || isDigit c || c == '-') name
        Nothing -> False

-- | Values of every @ name="..."@ attribute, with @&amp;@ decoded.
attributeValues :: T.Text -> T.Text -> [T.Text]
attributeValues name html =
  [ T.replace "&amp;" "&" (T.takeWhile (/= '"') (T.drop (T.length needle) rest))
  | (_, rest) <- T.breakOnAll needle html
  ]
  where
    needle = " " <> name <> "=\""
